# Prévia LTX-2.3 (LTX-2 Community License) na T4 grátis do Kaggle: A2Vid (foto + voz do editor) e T2V (cena da V1).
import subprocess, sys, os, time, base64, glob
W="/kaggle/working"; M="/tmp/m"; os.makedirs(M,exist_ok=True)
LOG=open(f"{W}/log.txt","a")
def log(*a):
    s=" ".join(str(x) for x in a); print(s,flush=True); LOG.write(s+"\n"); LOG.flush()
def sh(c, tol=False):
    t=time.time(); log("$",c[:300]); r=subprocess.run(c,shell=True,capture_output=True,text=True)
    log((r.stdout or "")[-3000:]); log((r.stderr or "")[-4000:]); log("rc",r.returncode,"t",round(time.time()-t),"s")
    if r.returncode and not tol: raise SystemExit(r.returncode)
    return r.returncode
open(f"{M}/foto.jpg","wb").write(base64.b64decode("")); open(f"{M}/voz.mp3","wb").write(base64.b64decode(""))
sh("nvidia-smi --query-gpu=name,memory.total --format=csv")
sh('pip install -q "git+https://github.com/Lightricks/LTX-2.git#subdirectory=packages/ltx-core" "git+https://github.com/Lightricks/LTX-2.git#subdirectory=packages/ltx-pipelines" hf_transfer')
os.environ["HF_HUB_ENABLE_HF_TRANSFER"]="1"
from huggingface_hub import hf_hub_download, snapshot_download
t=time.time()
CK=hf_hub_download("Lightricks/LTX-2.3","ltx-2.3-22b-dev.safetensors",local_dir=M)
LO=hf_hub_download("Lightricks/LTX-2.3","ltx-2.3-22b-distilled-lora-384-1.1.safetensors",local_dir=M)
UP=hf_hub_download("Lightricks/LTX-2.3","ltx-2.3-spatial-upscaler-x2-1.1.safetensors",local_dir=M)
G=snapshot_download("Lightricks/LTX-2",local_dir=f"{M}/gemma",allow_patterns=["text_encoder/model-*","text_encoder/model.safetensors.index.json","text_encoder/config.json","text_encoder/generation_config.json","tokenizer/*"])
log("downloads",round(time.time()-t),"s"); sh(f"du -sh {M}/*")
os.environ["PYTORCH_CUDA_ALLOC_CONF"]="expandable_segments:True"
COMUM=f"--checkpoint-path {CK} --distilled-lora {LO} 0.8 --spatial-upsampler-path {UP} --gemma-root {G} --quantization fp8-cast --offload cpu --frame-rate 24"
P1=("A Brazilian lawyer in his forties with short dark hair, a trimmed beard and dark-rimmed glasses, wearing a navy blazer and a light blue open-collar shirt, "
    "sits in front of a plain black studio background and speaks calmly and confidently straight to the camera, as in a video call. "
    "Natural lip movement matching the speech, small nods, steady gaze, soft side lighting, realistic, natural skin texture, sharp focus.")
P2=("A Brazilian woman in her fifties sits alone at a rustic wooden farmhouse kitchen table in late afternoon light, holding a smartphone with both hands, "
    "reading a message with a worried expression, a cup of coffee and an old framed photograph of an elderly man on the table, window light, "
    "realistic documentary footage, natural skin texture, quiet ambient room sound, no music, no dialogue.")
def rodar(nome, cmd):
    log("=====",nome); t=time.time(); rc=sh(cmd, tol=True); log("=====",nome,"rc",rc,"tempo",round(time.time()-t),"s")
    sh("nvidia-smi --query-gpu=memory.used --format=csv", tol=True)
    return rc
# 1) ensaio curto (2 s) para medir velocidade e memória
rc=rodar("A2V ensaio 2s", f'python -m ltx_pipelines.a2vid_two_stage {COMUM} --prompt "{P1}" --image {M}/foto.jpg 0 1.0 --audio-path {M}/voz.mp3 --audio-max-duration 2 --height 672 --width 384 --output-path {W}/ensaio_a2v.mp4')
# 2) prévia de 8 s (a fala inteira) com o editor
if rc==0:
    rodar("A2V editor 8s", f'python -m ltx_pipelines.a2vid_two_stage {COMUM} --prompt "{P1}" --image {M}/foto.jpg 0 1.0 --audio-path {M}/voz.mp3 --audio-max-duration 8 --height 672 --width 384 --seed 7 --output-path {W}/previa_editor_a2v.mp4')
# 3) cena da V1 com gente (texto para vídeo), 10 s
rodar("T2V Rosa 10s", f'python -m ltx_pipelines.ti2vid_two_stages {COMUM} --prompt "{P2}" --num-frames 241 --height 672 --width 384 --seed 11 --output-path {W}/previa_rosa_t2v.mp4')
log("fim"); sh(f"ls -la {W}", tol=True)
